/**
 * Catalog of DAX functions (Microsoft "DAX function reference"), used for
 * completion, signature help and hover tooltips in the DAX editor.
 *
 * Parameter names follow the Power BI IntelliSense spelling of the documented
 * parameters. INFO.* functions, EXTERNALMEASURE and visual-calculation-only
 * functions are intentionally omitted.
 */

export type DaxFunctionCategory =
  | 'Aggregation'
  | 'Date and time'
  | 'Time intelligence'
  | 'Filter'
  | 'Financial'
  | 'Information'
  | 'Logical'
  | 'Math and trig'
  | 'Other'
  | 'Parent and child'
  | 'Relationship'
  | 'Statistical'
  | 'Table manipulation'
  | 'Text'
  | 'Window'

export interface DaxParam {
  name: string
  optional?: boolean
  repeating?: boolean
  description?: string
}

export interface DaxFunctionInfo {
  name: string
  category: DaxFunctionCategory
  params: DaxParam[]
  returns: string
  description: string
}

/** Required parameter. */
const p = (name: string, description?: string): DaxParam => (description ? { name, description } : { name })
/** Optional parameter. */
const o = (name: string, description?: string): DaxParam => ({ ...p(name, description), optional: true })
/** Optional, repeating parameter (rendered as `[<Name>], ...`). */
const r = (name: string, description?: string): DaxParam => ({ ...p(name, description), optional: true, repeating: true })
/** Required, repeating parameter (rendered as `<Name>, ...`). */
const rr = (name: string, description?: string): DaxParam => ({ ...p(name, description), repeating: true })

const d = (
  name: string,
  category: DaxFunctionCategory,
  params: DaxParam[],
  returns: string,
  description: string
): DaxFunctionInfo => ({ name, category, params, returns, description })

