const BY_NAME = new Map(DAX_FUNCTIONS.map((f) => [f.name.toUpperCase(), f]))

export function findDaxFunction(name: string): DaxFunctionInfo | undefined {
  return BY_NAME.get(name.toUpperCase())
}

/** e.g. "CALCULATE(<Expression>, [<Filter1>], ...)" — PBI tooltip style: required params in <angle>, optional ones in [<square>], repeating ends with ", ..." */
export function formatSignature(f: DaxFunctionInfo): string {
  const parts = f.params.map((param) => {
    const s = param.optional ? `[<${param.name}>]` : `<${param.name}>`
    return param.repeating ? `${s}, ...` : s
  })
  return `${f.name}(${parts.join(', ')})`
}

